//! The wire types the webview sends in, and the one it gets back on failure.
//!
//! These are the shell's own types, not re-exported internals: the command
//! surface is allowed to grow by adding a field here, and `musa-project` is
//! never bent into a shape that exists only for a webview. Their TypeScript
//! is generated by `ts-rs` (`cargo test -p musa-desktop`), so the two sides
//! cannot drift.
//!
//! The snapshot travels the other way and is `musa-project`'s own
//! serialization — see the module documentation on [`crate::session`] for why
//! mirroring it here would create the drift this rule exists to prevent.

use std::path::PathBuf;

use musa_project::{
    ContainerKind, EditCommand, ExportRequest, GeneratedEditMode, GroupEdit, GroupIntent, HeaderField, InsertAt,
    NoteSpec, ProjectCommand, ProjectError, ReviewAction, ReviewAudition, Span, StudioEdit, Template, TextEdit,
    TransportRequest, Utf16Offsets,
};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::session::Request;

/// The command palette's preview of the exact project-owned barline plan.
#[derive(Clone, Debug, Serialize, TS)]
#[serde(tag = "status", rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub enum BarlinePreviewDto {
    Rewrite {
        revision: u64,
        inserted: usize,
        summary: String,
    },
    AlreadyBarred,
}

impl From<Option<&musa_project::BarlineRewrite>> for BarlinePreviewDto {
    fn from(rewrite: Option<&musa_project::BarlineRewrite>) -> Self {
        match rewrite {
            Some(rewrite) => Self::Rewrite {
                revision: rewrite.revision().0,
                inserted: rewrite.inserted(),
                summary: rewrite.summary(),
            },
            None => Self::AlreadyBarred,
        }
    }
}

/// A range of the source, in UTF-16 code units.
///
/// The webview's measure, not Rust's — the same one the spans in the snapshot
/// arrive in, so an edit can be built from a diagnostic without converting
/// anything. [`crate::session`] restates it in bytes before the session
/// applies it; see [`crate::offsets`] for why the boundary is here.
#[derive(Clone, Copy, Debug, Deserialize, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub struct SpanDto {
    pub start: u32,
    pub end: u32,
}

impl From<SpanDto> for Span {
    fn from(span: SpanDto) -> Self {
        Self {
            start: span.start,
            end: span.end,
        }
    }
}

/// One replacement against the current source.
#[derive(Clone, Debug, Deserialize, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub struct TextEditDto {
    pub span: SpanDto,
    pub replacement: String,
}

impl From<TextEditDto> for TextEdit {
    fn from(edit: TextEditDto) -> Self {
        Self::new(edit.span.into(), edit.replacement)
    }
}

/// What the user just did to the document.
///
/// Undo and redo are here rather than on `ProjectCommand` because the session
/// exposes them as history navigation, not as edits; from the webview's side
/// they are the same kind of request and belong on the same call.
#[derive(Clone, Debug, Deserialize, Serialize, TS)]
#[serde(tag = "kind", rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub enum CommandDto {
    #[serde(rename_all = "camelCase")]
    SetSource {
        source: String,
    },
    #[serde(rename_all = "camelCase")]
    ApplyEdits {
        edits: Vec<TextEditDto>,
    },
    #[serde(rename_all = "camelCase")]
    EditScore {
        edit: EditDto,
    },
    #[serde(rename_all = "camelCase")]
    EditStudio {
        edit: StudioEditDto,
    },
    Format,
    #[serde(rename_all = "camelCase")]
    InsertBarlines {
        revision: u64,
    },
    /// Commit one previewed group transformation, once.
    #[serde(rename_all = "camelCase")]
    ApplyGroupEdit {
        plan: u64,
        revision: u64,
    },
    Save,
    /// Take the work a crash left behind and make it the source.
    RestoreRecovery,
    /// Decline it, and stop being asked.
    DiscardRecovery,
    Undo,
    Redo,
    /// Read the open work again.
    ///
    /// The number is the webview's because a performance is a *label*, not a
    /// musical fact: the composer picks it, types it, and comes back to it.
    /// Everything the number means is the compiler's.
    #[serde(rename_all = "camelCase")]
    NewPerformance {
        performance: u64,
    },
    /// Keep one decision, so the next performance leaves it alone.
    #[serde(rename_all = "camelCase")]
    Keep {
        decision: String,
    },
    /// Let it go back to being drawn.
    #[serde(rename_all = "camelCase")]
    Release {
        decision: String,
    },
}

/// What to do when the edited event came out of an expansion (roadmap §9).
#[derive(Clone, Copy, Debug, Deserialize, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub enum GeneratedEditModeDto {
    /// Rewrite the motif; every occurrence changes.
    EditDefinition,
    /// Give this occurrence its own copy.
    Specialize,
}

impl From<GeneratedEditModeDto> for GeneratedEditMode {
    fn from(mode: GeneratedEditModeDto) -> Self {
        match mode {
            GeneratedEditModeDto::EditDefinition => Self::EditDefinition,
            GeneratedEditModeDto::Specialize => Self::Specialize,
        }
    }
}

/// One musical command against a selection (roadmap §11).
///
/// Five commands rather than one, because they are five different musical
/// questions: writing a value on every note, scaling the rhythm that is
/// already there, walking the staff, changing the sign, and moving by an
/// interval are not variants of "change the notes" (OMT ch. 009–012, 016).
/// A webview that offered one and a parameter would be deciding which of
/// them the composer meant.
#[derive(Clone, Debug, Deserialize, Serialize, TS)]
#[serde(tag = "kind", rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
pub enum GroupIntentDto {
    /// Write this duration on every selected event.
    #[serde(rename_all = "camelCase")]
    SetEachDuration { duration: String },
    /// Multiply every selected duration by this factor.
    #[serde(rename_all = "camelCase")]
    ScaleDurations { ratio: String },
    /// Move every selected pitch this many staff steps, sign unchanged.
    #[serde(rename_all = "camelCase")]
    MoveDiatonically { steps: i32 },
    /// Move every selected pitch this many semitones up the accidental
    /// ladder, notehead unchanged.
    #[serde(rename_all = "camelCase")]
    ShiftAccidentals { steps: i32 },
    /// Transpose every selected pitch by an interval the composer spelled.
    #[serde(rename_all = "camelCase")]
    TransposeBy { interval: String },
}

impl From<GroupIntentDto> for GroupIntent {
    fn from(intent: GroupIntentDto) -> Self {
        match intent {
            GroupIntentDto::SetEachDuration { duration } => Self::SetEachDuration { duration },
            GroupIntentDto::ScaleDurations { ratio } => Self::ScaleDurations { ratio },
            GroupIntentDto::MoveDiatonically { steps } => Self::MoveDiatonically { steps },
            GroupIntentDto::ShiftAccidentals { steps } => Self::ShiftAccidentals { steps },
            GroupIntentDto::TransposeBy { interval } => Self::TransposeBy { interval },
        }
    }
}

/// A selection and what to do to it.
#[derive(Clone, Debug, Deserialize, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../ui/src/lib/session/generated/")]
