impl CommandDto {
    /// The session request this stands for.
    ///
    /// The mapping lives here, on the exhaustive match, so a new variant is a
    /// compile error rather than a request that silently does nothing.
    pub(crate) fn into_request(self) -> Request {
        match self {
            Self::SetSource { source } => Request::Command(ProjectCommand::SetSource(source)),
            Self::ApplyEdits { edits } => {
                Request::Command(ProjectCommand::ApplyEdits(edits.into_iter().map(Into::into).collect()))
            }
            Self::EditScore { edit } => Request::Command(ProjectCommand::EditScore(edit.into())),
            Self::EditStudio { edit } => Request::Command(ProjectCommand::EditStudio(edit.into())),
            Self::Format => Request::Command(ProjectCommand::Format),
            Self::InsertBarlines { revision } => Request::Command(ProjectCommand::InsertBarlines {
                revision: musa_project::Revision(revision),
            }),
            Self::ApplyGroupEdit { plan, revision } => Request::Command(ProjectCommand::ApplyGroupEdit {
                plan,
                revision: musa_project::Revision(revision),
            }),
            Self::Save => Request::Command(ProjectCommand::Save),
            Self::RestoreRecovery => Request::Command(ProjectCommand::RestoreRecovery),
            Self::DiscardRecovery => Request::Command(ProjectCommand::DiscardRecovery),
            Self::Undo => Request::Undo,
            Self::Redo => Request::Redo,
            Self::NewPerformance { performance } => Request::Command(ProjectCommand::NewPerformance { performance }),
            Self::Keep { decision } => Request::Command(ProjectCommand::Pin(decision)),
            Self::Release { decision } => Request::Command(ProjectCommand::Unpin(decision)),
        }
    }
}

